sudo -n -u aegis_pep env PYTHONPATH=/tmp/aegis_v3e_sandbox/pylibs:/tmp/aegis_v3e_sandbox/app /usr/bin/python3 -c import sqlite3,json
con=sqlite3.connect('/tmp/aegis_v3e_sandbox/state/pep_ledger.db')
